  static unsigned getHashValue(const GVNPass::Expression &E) {
    using llvm::hash_value;

    return static_cast<unsigned>(hash_value(E));
  }

  static bool isEqual(const GVNPass::Expression &LHS,
                      const GVNPass::Expression &RHS) {
    return LHS == RHS;
  }
};

